   end=s.find('\n`,',m.end());end=end+3 if end>=0 else s.find('`,',m.end())+2
   return {'path':path,'anchor':anchor,'resolvedSymbol':resolved,'locatorType':'Phase2 descriptive locator resolved to current JS template symbol, not an HTML anchor','exists':True,'anchorFound':True,'line':s[:m.start()].count('\n')+1,'text':s[m.start():end],'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
